func:
// Événements des 7 derniers jours (pour les compteurs et la liste de la vue technique).
msg.params = { $depuis: new Date(Date.now() - 7 * 86400000).toISOString() };
return msg;

// Renvoie les événements enregistrés vers les tableaux de bord, comme s'ils venaient de S2.
const messages = (msg.payload || []).map(l => {
    let e = {};
    try { e = JSON.parse(l.details); } catch (err) { e = { type: "inconnu" }; }
    if (!e.received_at) e.received_at = l.received_at;
    return { topic: "pce92/evenements", replay: true, payload: e };
});
node.status({ fill: "blue", shape: "dot", text: messages.length + " événement(s) rechargé(s)" });
return [messages];

// Requête « 7 derniers jours ». msg.node_id = un capteur précis, ou absent = tous les capteurs.
// msg.jours = nombre de jours (7 par défaut).
const jours = Number(msg.jours) > 0 ? Number(msg.jours) : 7;
msg.params = {
    $depuis: new Date(Date.now() - jours * 86400000).toISOString(),
    $node_id: (msg.node_id === undefined || msg.node_id === null || msg.node_id === "") ? null : Number(msg.node_id)
};
return msg;

// Au démarrage : renvoie l'historique des 7 derniers jours vers les tableaux de bord,
// sous la même forme que les mesures publiées par S2, marqué replay = true.
const lignes = msg.payload || [];
const messages = lignes.map(l => ({
    topic: "pce92/mesures/" + l.node_id,
    replay: true,
    payload: {
        node_id: l.node_id, received_at: l.received_at,
        water_mm: l.water_mm, water_valid: l.water_valid === 1,
        batt_v: l.batt_v, seq: l.seq, alert: l.alert === 1, next_min: l.next_min,
        expected_next_at: l.next_min === null ? null
            : new Date(Date.parse(l.received_at) + l.next_min * 60000).toISOString(),
        lost_before: l.lost_before, rssi: l.rssi, snr: l.snr, source: l.source, payload_hex: l.payload_hex
    }
}));
node.status({ fill: "blue", shape: "dot", text: messages.length + " mesure(s) rechargée(s)" });
return [messages];

// Prépare l'enregistrement d'une mesure (topic pce92/mesures/<node_id>, publié par S2).
const m = msg.payload;
if (!m || typeof m.node_id !== "number" || !m.received_at) {
    node.warn("Mesure ignorée : format inattendu");
    return null;
}
const b = (v) => (v ? 1 : 0);
msg.params = {
    $node_id: m.node_id,
    $received_at: new Date(m.received_at).toISOString(),   // format unique, pour trier et filtrer
    $water_mm: m.water_valid ? m.water_mm : null,
    $water_valid: b(m.water_valid),
    $batt_v: m.batt_v ?? null,
    $seq: m.seq,
    $alert: b(m.alert),
    $next_min: m.next_min ?? null,
    $lost_before: m.lost_before || 0,
    $rssi: m.rssi ?? null,
    $snr: m.snr ?? null,
    $source: m.source ?? null,
    $payload_hex: m.payload_hex ?? null
};
return msg;

// Prépare l'enregistrement d'un événement (topic pce92/evenements, publié par S2).
const e = msg.payload || {};
msg.params = {
    $received_at: new Date(e.received_at || Date.now()).toISOString(),
    $type: e.type || "inconnu",
    $node_id: e.node_id ?? null,
    $seq: e.seq ?? null,
    $details: JSON.stringify(e)
};
return msg;

// Requête « 7 derniers jours ». msg.node_id = un capteur précis, ou absent = tous les capteurs.
// msg.jours = nombre de jours (7 par défaut).
const jours = Number(msg.jours) > 0 ? Number(msg.jours) : 7;
msg.params = {
    $depuis: new Date(Date.now() - jours * 86400000).toISOString(),
    $node_id: (msg.node_id === undefined || msg.node_id === null || msg.node_id === "") ? null : Number(msg.node_id)
};
return msg;

// Résume le résultat de la requête dans le panneau debug.
const lignes = msg.payload || [];
const parCapteur = {};
for (const l of lignes) parCapteur[l.node_id] = (parCapteur[l.node_id] || 0) + 1;
node.status({ fill: "green", shape: "dot", text: lignes.length + " mesure(s) sur 7 jours" });
msg.resume = { total: lignes.length, par_capteur: parCapteur,
               premiere: lignes.length ? lignes[0].received_at : null,
               derniere: lignes.length ? lignes[lignes.length - 1].received_at : null };
return msg;

// GET /pce92/mesures?node_id=3&jours=7&format=csv
const q = msg.req.query || {};
const jours = Math.min(Math.max(Number(q.jours) || 7, 1), 366);
msg.format = q.format === "csv" ? "csv" : "json";
msg.params = {
    $depuis: new Date(Date.now() - jours * 86400000).toISOString(),
    $node_id: q.node_id ? Number(q.node_id) : null
};
return msg;

// Met en forme la réponse : JSON (par défaut) ou CSV (export, par ex. pour OPALimpact).
const lignes = (msg.payload || []).map(l => Object.assign({}, l,
    { water_valid: l.water_valid === 1, alert: l.alert === 1 }));
if (msg.format === "csv") {
    const colonnes = ["node_id", "received_at", "water_mm", "water_valid", "batt_v", "seq", "alert",
                      "next_min", "lost_before", "rssi", "snr", "source", "payload_hex"];
    const csv = [colonnes.join(",")].concat(
        lignes.map(l => colonnes.map(c => (l[c] === null || l[c] === undefined) ? "" : l[c]).join(","))
    ).join("\n");
    msg.payload = csv;
    msg.headers = { "Content-Type": "text/csv; charset=utf-8",
                    "Content-Disposition": "attachment; filename=pce92_mesures.csv" };
} else {
    msg.payload = lignes;
    msg.headers = { "Content-Type": "application/json; charset=utf-8" };
}
msg.statusCode = 200;
return msg;
